import React, { useState, useEffect } from 'react';
import { digitalTwinApi, machineApi } from '../api/client';
import {
  Cpu,
  Activity,
  Zap,
  Gauge,
  Thermometer,
  Sparkles,
  AlertTriangle,
  Play,
  Pause,
  RotateCcw,
  Wrench,
  Search,
  Sliders,
  CheckCircle2,
  Clock,
  Radio,
  ArrowRightLeft,
  Server,
  Building,
  MapPin,
  FileText,
} from 'lucide-react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import { Line } from 'react-chartjs-2';
import { useNavigate } from 'react-router-dom';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const DigitalTwinPage = () => {
  const navigate = useNavigate();

  // Machine Selection State
  const [selectedMachineId, setSelectedMachineId] = useState('LOOM-201');
  const [compareMachineId, setCompareMachineId] = useState('LOOM-101');
  const [showComparison, setShowComparison] = useState(false);

  // Digital Twin Data Payload
  const [twinData, setTwinData] = useState(null);
  const [loading, setLoading] = useState(true);

  // Selected Component Inspection Modal State
  const [selectedComponent, setSelectedComponent] = useState(null);

  // Sensor History Filter State
  const [historyTimeRange, setHistoryTimeRange] = useState('Today');

  // Historical Playback Control State
  const [isPlaying, setIsPlaying] = useState(false);
  const [playbackTime, setPlaybackTime] = useState('10:40 AM');

  useEffect(() => {
    fetchTwinData(selectedMachineId);
  }, [selectedMachineId]);

  // Live ticking playback interval
  useEffect(() => {
    if (!isPlaying) return;
    const times = ['08:00 AM', '09:00 AM', '10:00 AM', '11:00 AM', '12:00 PM'];
    let idx = 0;
    const interval = setInterval(() => {
      setPlaybackTime(times[idx % times.length]);
      idx++;
    }, 2000);
    return () => clearInterval(interval);
  }, [isPlaying]);

  const fetchTwinData = async (mId) => {
    try {
      setLoading(true);
      const res = await digitalTwinApi.getByMachineId(mId);
      if (res && res.data && res.data.success) {
        setTwinData(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch twin data:', err);
    } finally {
      setLoading(false);
    }
  };

  // Fallback defaults matching requirements
  const twin = twinData || {
    machineId: selectedMachineId,
    assetName: `Dornier Heavy Air Jet Loom (${selectedMachineId})`,
    manufacturer: 'Dornier',
    model: 'HD-2025',
    installedYear: 2024,
    location: 'Plant A - Coimbatore Hub',
    department: 'High-Speed Weaving',
    twinStatus: {
      syncPct: 99.8,
      lastSync: '1 sec ago',
      latencyMs: 32,
      mqttState: 'Connected',
      twinState: 'Healthy',
    },
    mqttDetails: {
      topic: `textwin/telemetry/${selectedMachineId}`,
      lastMessage: '10:35:22',
      qos: 1,
      packets: 2543,
      latencyMs: 24,
    },
    energy: {
      powerKw: 6.5,
      todayEnergyKwh: 126,
      efficiencyPct: 96,
    },
    components: [
      { name: 'Bearing', status: 'normal', color: '#22C55E', temp: '54.2°C', rpm: 1050, vibration: '0.18 mm/s', health: '96%', lastMaint: '15 Jul 2026' },
      { name: 'Motor', status: 'warning', color: '#EF4444', temp: '82.4°C', rpm: 1080, vibration: '0.34 mm/s', health: '68%', lastMaint: '10 Jun 2026' },
      { name: 'Air Nozzle', status: 'caution', color: '#F59E0B', temp: '48.0°C', rpm: 1050, vibration: '0.12 mm/s', health: '85%', lastMaint: '01 Jul 2026' },
      { name: 'Warp Beam', status: 'normal', color: '#22C55E', temp: '38.5°C', rpm: 980, vibration: '0.08 mm/s', health: '98%', lastMaint: '20 May 2026' },
      { name: 'Weft Sensor', status: 'critical', color: '#EF4444', temp: '41.2°C', rpm: 1050, vibration: '0.22 mm/s', health: '62%', lastMaint: '12 Jul 2026' },
    ],
    events: [
      { time: '10:40', text: 'Maintenance Scheduled for Motor Drive Shaft' },
      { time: '10:35', text: 'Engineer Assigned: Rajesh Kumar' },
      { time: '10:32', text: 'AI Prediction Generated: 82% Failure Probability' },
      { time: '10:25', text: 'Bearing Fatigue Warning Threshold Exceeded' },
      { time: '10:20', text: 'Temperature Increased above 80.0°C' },
    ],
    aiPrediction: {
      healthScore: 68,
      failureProbability: 82,
      remainingUsefulLifeHours: 34,
      recommendation: 'Replace Drive Shaft Bearing within 12 hrs',
      rootCause: 'Bearing Fatigue & Thermal Friction',
      confidenceScore: 96,
    },
    maintenanceHistory: {
      lastMaintenanceDate: '15 Jul 2026',
      lastTask: 'Bearing Replacement & Lube Calibration',
      engineer: 'Rajesh Kumar',
      nextMaintenanceDate: '15 Aug 2026',
    },
  };

  // Live Chart Datasets
  const chartLabels = ['08:00', '08:30', '09:00', '09:30', '10:00', '10:30', '11:00'];
  const sensorChartData = {
    labels: chartLabels,
    datasets: [
      {
        label: 'Temperature (°C)',
        data: [52, 54, 58, 64, 72, 79, 82],
        borderColor: '#EF4444',
        backgroundColor: 'rgba(239, 68, 68, 0.1)',
        tension: 0.4,
        fill: true,
      },
      {
        label: 'Speed (RPM)',
        data: [1020, 1040, 1050, 1060, 1050, 1080, 1075],
        borderColor: '#2563EB',
        backgroundColor: 'transparent',
        tension: 0.4,
      },
      {
        label: 'Vibration (mm/s)',
        data: [0.12, 0.14, 0.16, 0.19, 0.24, 0.31, 0.34],
        borderColor: '#8B5CF6',
        backgroundColor: 'transparent',
        tension: 0.4,
      },
      {
        label: 'Air Pressure (bar)',
        data: [4.8, 4.8, 4.7, 4.6, 4.5, 4.4, 4.2],
        borderColor: '#06B6D4',
        backgroundColor: 'transparent',
        tension: 0.4,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { position: 'top', labels: { font: { family: 'Plus Jakarta Sans', size: 11, weight: '700' } } },
    },
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>

      {/* 12. MACHINE INFORMATION & SELECTOR HEADER */}
      <div
        className="glass-card"
        style={{
          padding: '1.25rem 1.5rem',
          display: 'flex',
          justify: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: '1rem',
          background: '#ffffff',
          border: '1px solid #E2E8F0',
          borderRadius: '12px',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
          <div
            style={{
              width: '48px',
              height: '48px',
              borderRadius: '10px',
              background: '#EFF6FF',
              color: '#2563EB',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <Cpu size={26} />
          </div>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
              <h2 style={{ fontSize: '1.35rem', fontWeight: '800', color: '#0F172A' }}>{twin.assetName}</h2>
              <span className="badge" style={{ background: '#DCFCE7', color: '#166534', fontWeight: '800' }}>3D Twin Sync</span>
            </div>
            <p style={{ fontSize: '0.82rem', color: '#64748B', fontWeight: '700', marginTop: '2px' }}>
              ID: <strong style={{ color: '#2563EB', fontFamily: 'JetBrains Mono, monospace' }}>{twin.machineId}</strong> • Mfr: {twin.manufacturer} • Model: {twin.model} ({twin.installedYear}) • {twin.location} • {twin.department}
            </p>
          </div>
        </div>

        {/* Machine Selector & Twin Comparison Button */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <select
            className="form-control"
            value={selectedMachineId}
            onChange={(e) => setSelectedMachineId(e.target.value)}
            style={{ width: '160px', fontWeight: '800', borderColor: '#2563EB' }}
          >
            <option value="LOOM-201">LOOM-201 (Bay A)</option>
            <option value="LOOM-101">LOOM-101 (Bay A)</option>
            <option value="LOOM-104">LOOM-104 (Bay B)</option>
            <option value="LOOM-301">LOOM-301 (Bay C)</option>
            <option value="LOOM-501">LOOM-501 (Bay E)</option>
          </select>

          <button
            className="btn btn-secondary btn-sm"
            onClick={() => setShowComparison(!showComparison)}
            style={{ fontWeight: '800' }}
          >
            <ArrowRightLeft size={16} /> {showComparison ? 'Close Twin Compare' : '13. Twin Compare'}
          </button>

          <button
            className="btn btn-primary btn-sm"
            onClick={() => navigate('/what-if')}
            style={{ background: '#F59E0B', borderColor: '#F59E0B', color: '#ffffff', fontWeight: '800' }}
          >
            <Sparkles size={16} /> 9. Run What-If Simulation
          </button>
        </div>
      </div>

      {/* 13. SIDE-BY-SIDE TWIN COMPARISON VIEW */}
      {showComparison && (
        <div className="glass-card" style={{ padding: '1.25rem', background: '#F8FAFC', border: '1px solid #2563EB', borderRadius: '12px' }}>
          <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#2563EB', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <ArrowRightLeft size={18} /> Digital Twin Comparison View: {selectedMachineId} VS {compareMachineId}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '1.25rem' }}>
            {/* Left Machine */}
            <div style={{ padding: '1rem', background: '#ffffff', borderRadius: '8px', border: '1px solid #E2E8F0' }}>
              <h4 style={{ fontWeight: '800', color: '#0F172A' }}>Primary: {selectedMachineId}</h4>
              <div style={{ fontSize: '0.85rem', color: '#64748B', marginTop: '0.5rem', display: 'flex', flexDirection: 'column', gap: '0.3rem', fontWeight: '700' }}>
                <div>Health Score: <strong style={{ color: '#EF4444' }}>68% (At Risk)</strong></div>
                <div>Operating Speed: <strong>1,080 RPM</strong></div>
                <div>Motor Temp: <strong style={{ color: '#EF4444' }}>82.4°C</strong></div>
                <div>Daily Production: <strong>14,250 Meters</strong></div>
              </div>
            </div>

            {/* Right Machine */}
            <div style={{ padding: '1rem', background: '#ffffff', borderRadius: '8px', border: '1px solid #E2E8F0' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h4 style={{ fontWeight: '800', color: '#0F172A' }}>Compared: {compareMachineId}</h4>
                <select
                  className="form-control form-control-sm"
                  value={compareMachineId}
                  onChange={(e) => setCompareMachineId(e.target.value)}
                  style={{ width: '120px' }}
                >
                  <option value="LOOM-101">LOOM-101</option>
                  <option value="LOOM-104">LOOM-104</option>
                  <option value="LOOM-301">LOOM-301</option>
                </select>
              </div>
              <div style={{ fontSize: '0.85rem', color: '#64748B', marginTop: '0.5rem', display: 'flex', flexDirection: 'column', gap: '0.3rem', fontWeight: '700' }}>
                <div>Health Score: <strong style={{ color: '#22C55E' }}>96% (Optimal)</strong></div>
                <div>Operating Speed: <strong>1,050 RPM</strong></div>
                <div>Motor Temp: <strong style={{ color: '#22C55E' }}>54.2°C</strong></div>
                <div>Daily Production: <strong>15,800 Meters</strong></div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* TOP GRID: 3D SVG VISUALIZATION (LEFT) + AI PREDICTION (RIGHT) */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(360px, 1fr))', gap: '1.25rem' }}>

        {/* 1 & 7. 3D / SVG INTERACTIVE MACHINE VISUALIZATION WITH BLINKING LED INDICATORS */}
        <div className="glass-card" style={{ padding: '1.5rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
            <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Cpu size={18} style={{ color: '#2563EB' }} /> 1. Air Jet Loom Interactive 3D Component Diagram
            </h3>
            <span style={{ fontSize: '0.72rem', color: '#64748B', fontWeight: '700' }}>Click Component to Inspect</span>
          </div>

          {/* Interactive SVG Diagram Container */}
          <div
            style={{
              height: '240px',
              background: '#F8FAFC',
              border: '1.5px dashed #CBD5E1',
              borderRadius: '10px',
              position: 'relative',
              display: 'flex',
              alignItems: 'center',
              justify: 'center',
              overflow: 'hidden',
            }}
          >
            {/* SVG Machine Graphic */}
            <svg width="320" height="180" viewBox="0 0 320 180" fill="none">
              <rect x="20" y="40" width="280" height="100" rx="8" fill="#E2E8F0" stroke="#94A3B8" strokeWidth="2" />
              <line x1="40" y1="140" x2="40" y2="170" stroke="#475569" strokeWidth="4" />
              <line x1="280" y1="140" x2="280" y2="170" stroke="#475569" strokeWidth="4" />
              <circle cx="80" cy="90" r="30" fill="#CBD5E1" stroke="#2563EB" strokeWidth="3" />
              <path d="M140 60 L240 60 L240 120 L140 120 Z" fill="#94A3B8" opacity="0.4" />
            </svg>

            {/* Clickable Component Hotspots with Blinking Indicators */}
            {twin.components.map((c, idx) => {
              const positions = [
                { top: '35%', left: '25%' }, // Bearing
                { top: '25%', left: '75%' }, // Motor
                { top: '65%', left: '60%' }, // Air Nozzle
                { top: '70%', left: '20%' }, // Warp Beam
                { top: '45%', left: '85%' }, // Weft Sensor
              ];
              const pos = positions[idx % positions.length];

              return (
                <div
                  key={c.name}
                  onClick={() => setSelectedComponent(c)}
                  style={{
                    position: 'absolute',
                    top: pos.top,
                    left: pos.left,
                    transform: 'translate(-50%, -50%)',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.35rem',
                    background: '#ffffff',
                    padding: '0.35rem 0.6rem',
                    borderRadius: '20px',
                    border: `1.5px solid ${c.color}`,
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                  }}
                >
                  {/* Blinking LED Indicator */}
                  <span
                    style={{
                      width: '10px',
                      height: '10px',
                      borderRadius: '50%',
                      background: c.color,
                      boxShadow: `0 0 8px ${c.color}`,
                      animation: c.status !== 'normal' ? 'pulse 1.2s infinite' : 'none',
                    }}
                  />
                  <span style={{ fontSize: '0.74rem', fontWeight: '800', color: '#0F172A' }}>{c.name}</span>
                </div>
              );
            })}
          </div>

          {/* Component Inspection Popover Box */}
          {selectedComponent ? (
            <div style={{ marginTop: '1rem', padding: '0.85rem 1.1rem', background: '#EFF6FF', border: '1px solid #2563EB', borderRadius: '8px' }}>
              <div style={{ fontSize: '0.88rem', fontWeight: '800', color: '#2563EB', display: 'flex', justifyContent: 'space-between' }}>
                <span>🔍 Component Inspection: {selectedComponent.name}</span>
                <span style={{ color: selectedComponent.color, fontWeight: '900' }}>Health: {selectedComponent.health}</span>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '0.5rem', marginTop: '0.5rem', fontSize: '0.78rem', color: '#0F172A', fontWeight: '700' }}>
                <div>Temp: <strong>{selectedComponent.temp}</strong></div>
                <div>RPM: <strong>{selectedComponent.rpm}</strong></div>
                <div>Vib: <strong>{selectedComponent.vibration}</strong></div>
                <div>Last Maint: <strong>{selectedComponent.lastMaint}</strong></div>
              </div>
            </div>
          ) : (
            <div style={{ marginTop: '0.75rem', fontSize: '0.76rem', color: '#64748B', textAlign: 'center', fontWeight: '600' }}>
              💡 Click any component label above (Motor, Bearing, Air Nozzle) to view real-time diagnostics.
            </div>
          )}
        </div>

        {/* 3, 8 & 11. AI PREDICTION PANEL & ROOT CAUSE */}
        <div className="glass-card" style={{ padding: '1.5rem', background: '#F5F3FF', border: '1px solid #8B5CF6', borderRadius: '12px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
            <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Sparkles size={18} style={{ color: '#8B5CF6' }} /> 3. AI Predictive Diagnostics Matrix
            </h3>
            <span className="badge" style={{ background: '#8B5CF6', color: '#ffffff', fontWeight: '800' }}>RUL XGBoost v4</span>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.85rem', marginBottom: '1.25rem' }}>
            <div style={{ padding: '0.85rem', background: '#ffffff', borderRadius: '8px', border: '1px solid #C4B5FD' }}>
              <div style={{ fontSize: '0.72rem', color: '#64748B', fontWeight: '800' }}>HEALTH SCORE</div>
              <div style={{ fontSize: '1.6rem', fontWeight: '900', color: '#EF4444', marginTop: '2px' }}>{twin.aiPrediction.healthScore}%</div>
            </div>
            <div style={{ padding: '0.85rem', background: '#ffffff', borderRadius: '8px', border: '1px solid #C4B5FD' }}>
              <div style={{ fontSize: '0.72rem', color: '#64748B', fontWeight: '800' }}>FAILURE PROB.</div>
              <div style={{ fontSize: '1.6rem', fontWeight: '900', color: '#EF4444', marginTop: '2px' }}>{twin.aiPrediction.failureProbability}%</div>
            </div>
            <div style={{ padding: '0.85rem', background: '#ffffff', borderRadius: '8px', border: '1px solid #C4B5FD' }}>
              <div style={{ fontSize: '0.72rem', color: '#64748B', fontWeight: '800' }}>REMAINING RUL</div>
              <div style={{ fontSize: '1.6rem', fontWeight: '900', color: '#F59E0B', marginTop: '2px' }}>{twin.aiPrediction.remainingUsefulLifeHours} Hrs</div>
            </div>
          </div>

          {/* 8. AI Root Cause & Confidence */}
          <div style={{ padding: '1rem', background: '#ffffff', borderRadius: '8px', border: '1px solid #8B5CF6', marginBottom: '1rem' }}>
            <div style={{ fontSize: '0.8rem', fontWeight: '800', color: '#8B5CF6' }}>🤖 AI ROOT CAUSE & CONFIDENCE</div>
            <div style={{ fontSize: '1rem', fontWeight: '800', color: '#0F172A', marginTop: '4px' }}>
              {twin.aiPrediction.rootCause} <span style={{ color: '#2563EB', fontSize: '0.82rem' }}>({twin.aiPrediction.confidenceScore}% Confidence)</span>
            </div>
            <div style={{ fontSize: '0.82rem', color: '#EF4444', fontWeight: '800', marginTop: '4px' }}>
              Recommendation: {twin.aiPrediction.recommendation}
            </div>
          </div>

          {/* 11. Energy Monitoring */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem', padding: '0.75rem', background: '#ffffff', borderRadius: '8px', border: '1px solid #E2E8F0' }}>
            <div>
              <div style={{ fontSize: '0.68rem', color: '#64748B', fontWeight: '800' }}>POWER LOAD</div>
              <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A' }}>{twin.energy.powerKw} kW</div>
            </div>
            <div>
              <div style={{ fontSize: '0.68rem', color: '#64748B', fontWeight: '800' }}>TODAY'S ENERGY</div>
              <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A' }}>{twin.energy.todayEnergyKwh} kWh</div>
            </div>
            <div>
              <div style={{ fontSize: '0.68rem', color: '#64748B', fontWeight: '800' }}>EFFICIENCY</div>
              <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#22C55E' }}>{twin.energy.efficiencyPct}%</div>
            </div>
          </div>
        </div>
      </div>

      {/* 2 & 10. LIVE SENSOR GRAPHS & HISTORY FILTERS */}
      <div className="glass-card" style={{ padding: '1.5rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', flexWrap: 'wrap', gap: '0.75rem' }}>
          <div>
            <h3 style={{ fontSize: '1.05rem', fontWeight: '800', color: '#0F172A', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
              <Activity size={18} style={{ color: '#2563EB' }} /> 2. Live Sensor Telemetry Charts (MongoDB Feed)
            </h3>
            <span style={{ fontSize: '0.78rem', color: '#64748B' }}>Temperature, Speed, Vibration & Air Pressure Signals</span>
          </div>

          {/* 10. Sensor History Time Range Selector */}
          <div className="tab-nav" style={{ marginBottom: 0 }}>
            {['Today', 'Yesterday', '7 Days', '30 Days'].map((t) => (
              <button
                key={t}
                className={`tab-btn ${historyTimeRange === t ? 'active' : ''}`}
                onClick={() => setHistoryTimeRange(t)}
                style={{ fontSize: '0.76rem', padding: '0.35rem 0.75rem' }}
              >
                {t}
              </button>
            ))}
          </div>
        </div>

        <div style={{ height: '220px', width: '100%' }}>
          <Line data={sensorChartData} options={chartOptions} />
        </div>
      </div>

      {/* 5. HISTORICAL PLAYBACK CONTROL BAR */}
      <div className="glass-card" style={{ padding: '1.25rem 1.5rem', background: '#EFF6FF', border: '1px solid #2563EB', borderRadius: '12px', display: 'flex', alignItems: 'center', gap: '1.25rem', flexWrap: 'wrap' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <button className="btn btn-primary btn-sm" onClick={() => setIsPlaying(!isPlaying)} style={{ background: '#2563EB' }}>
            {isPlaying ? <><Pause size={14} /> Pause Replay</> : <><Play size={14} /> 5. Play History</>}
          </button>
          <span style={{ fontSize: '0.85rem', fontWeight: '800', color: '#2563EB' }}>Replay Timestamp: {playbackTime}</span>
        </div>

        <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
          <span style={{ fontSize: '0.75rem', fontWeight: '800', color: '#64748B' }}>08:00 AM</span>
          <input
            type="range"
            min="1"
            max="5"
            step="1"
            className="form-range"
            style={{ flex: 1, accentColor: '#2563EB' }}
            onChange={(e) => {
              const times = ['08:00 AM', '09:00 AM', '10:00 AM', '11:00 AM', '12:00 PM'];
              setPlaybackTime(times[e.target.value - 1]);
            }}
          />
          <span style={{ fontSize: '0.75rem', fontWeight: '800', color: '#64748B' }}>12:00 PM</span>
        </div>
      </div>

      {/* BOTTOM GRID: MAINTENANCE HISTORY (LEFT) + EVENT TIMELINE (RIGHT) + MQTT & TWIN STATUS (BOTTOM) */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '1.25rem' }}>

        {/* 6. MAINTENANCE HISTORY (MYSQL) */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <h3 style={{ fontSize: '1rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Wrench size={16} style={{ color: '#F97316' }} /> 6. Maintenance History (MySQL Record)
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', fontSize: '0.85rem' }}>
            <div style={{ padding: '0.75rem', background: '#FFF7ED', borderRadius: '8px', border: '1px solid #F97316' }}>
              <div style={{ fontSize: '0.74rem', color: '#C2410C', fontWeight: '800' }}>LAST MAINTENANCE COMPLETED</div>
              <div style={{ fontWeight: '800', color: '#0F172A', marginTop: '2px' }}>{twin.maintenanceHistory.lastTask}</div>
              <div style={{ fontSize: '0.78rem', color: '#64748B', marginTop: '2px', fontWeight: '700' }}>
                Date: {twin.maintenanceHistory.lastMaintenanceDate} • Engineer: {twin.maintenanceHistory.engineer}
              </div>
            </div>

            <div style={{ padding: '0.75rem', background: '#F8FAFC', borderRadius: '8px', border: '1px solid #E2E8F0' }}>
              <div style={{ fontSize: '0.74rem', color: '#2563EB', fontWeight: '800' }}>NEXT SCHEDULED SERVICING</div>
              <div style={{ fontWeight: '800', color: '#0F172A', marginTop: '2px' }}>Preventive Lube & Transducer Check</div>
              <div style={{ fontSize: '0.78rem', color: '#64748B', marginTop: '2px', fontWeight: '700' }}>
                Target Date: {twin.maintenanceHistory.nextMaintenanceDate}
              </div>
            </div>
          </div>
        </div>

        {/* 14. DIGITAL TWIN EVENT TIMELINE */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <h3 style={{ fontSize: '1rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Clock size={16} style={{ color: '#2563EB' }} /> 14. Digital Twin Event Timeline
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
            {twin.events.map((ev, idx) => (
              <div key={idx} style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', fontSize: '0.8rem' }}>
                <span style={{ fontFamily: 'JetBrains Mono', color: '#2563EB', fontWeight: '800', minWidth: '45px' }}>{ev.time}</span>
                <span style={{ color: '#0F172A', fontWeight: '700' }}>{ev.text}</span>
              </div>
            ))}
          </div>
        </div>

        {/* 4 & 15. DIGITAL TWIN STATUS & MQTT LIVE MESSAGES */}
        <div className="glass-card" style={{ padding: '1.25rem', background: '#ffffff', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
          <h3 style={{ fontSize: '1rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Radio size={16} style={{ color: '#06B6D4' }} /> 4 & 15. Twin Sync & MQTT Message Stream
          </h3>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '0.75rem', fontSize: '0.78rem' }}>
            <div style={{ padding: '0.65rem', background: '#F8FAFC', borderRadius: '6px', border: '1px solid #E2E8F0' }}>
              <div style={{ color: '#64748B', fontWeight: '700' }}>TWIN SYNC</div>
              <div style={{ fontSize: '1.1rem', fontWeight: '900', color: '#22C55E' }}>{twin.twinStatus.syncPct}%</div>
              <div style={{ fontSize: '0.7rem', color: '#64748B' }}>Last Sync: {twin.twinStatus.lastSync}</div>
            </div>

            <div style={{ padding: '0.65rem', background: '#F8FAFC', borderRadius: '6px', border: '1px solid #E2E8F0' }}>
              <div style={{ color: '#64748B', fontWeight: '700' }}>MQTT LATENCY</div>
              <div style={{ fontSize: '1.1rem', fontWeight: '900', color: '#2563EB' }}>{twin.twinStatus.latencyMs} ms</div>
              <div style={{ fontSize: '0.7rem', color: '#059669', fontWeight: '800' }}>State: Connected</div>
            </div>
          </div>

          <div style={{ marginTop: '0.75rem', padding: '0.65rem', background: '#F8FAFC', borderRadius: '6px', fontSize: '0.76rem', color: '#475569', fontWeight: '700' }}>
            <div>MQTT Topic: <strong style={{ color: '#2563EB', fontFamily: 'JetBrains Mono' }}>{twin.mqttDetails.topic}</strong></div>
            <div>Packets Received: <strong>{twin.mqttDetails.packets.toLocaleString()}</strong> (QoS {twin.mqttDetails.qos})</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DigitalTwinPage;
